def fresh(name,data):
 p=out/name; assert not p.exists(),p
 t=out/(name+'.tmp'); assert not t.exists(),t
 with t.open('xb') as f: f.write(data); f.flush(); os.fsync(f.fileno())
 assert t.read_bytes()==data
 os.replace(t,p)
 return {'path':p.as_posix(),'sha256':hashlib.sha256(data).hexdigest(),'bytes':len(data)}
